    void LegacyUpdate(){float dt=Mathf.Min(Time.deltaTime,.05f);if(Input.GetKeyDown(KeyCode.Escape)){if(phase==Phase.Play)Pause();else if(phase==Phase.Pause)phase=Phase.Play;}noticeTime=Mathf.Max(0,noticeTime-dt);
        if(phase==Phase.Play){elapsed+=dt;ReadTouch();Vector2 movement=stick;if(!smoke){movement+=new Vector2((Input.GetKey(KeyCode.D)||Input.GetKey(KeyCode.RightArrow)?1:0)-(Input.GetKey(KeyCode.A)||Input.GetKey(KeyCode.LeftArrow)?1:0),(Input.GetKey(KeyCode.S)||Input.GetKey(KeyCode.DownArrow)?1:0)-(Input.GetKey(KeyCode.W)||Input.GetKey(KeyCode.UpArrow)?1:0));if(Input.GetMouseButton(1)){yaw+=Input.GetAxis("Mouse X")*3;pitch=Mathf.Clamp(pitch-Input.GetAxis("Mouse Y")*2,12,50);}if(Input.GetKeyDown(KeyCode.J))Strike();if(Input.GetKeyDown(KeyCode.E))Burst();if(Input.GetKeyDown(KeyCode.LeftShift))Dodge();if(Input.GetKeyDown(KeyCode.Space))Jump();if(Input.GetKeyDown(KeyCode.F))Collect();}Move(movement,dt);UpdateFoes(dt);saveClock+=dt;if(saveClock>15){saveClock=0;SaveJourney(false);}}
        if(phase!=Phase.Pause){for(int i=pulses.Count-1;i>=0;i--){var p=pulses[i];p.life-=dt;if(p.life<=0){Destroy(p.root.gameObject);pulses.RemoveAt(i);}else{float size=Mathf.Lerp(.3f,p.radius,1-p.life/p.max);p.root.localScale=V(size*2,.015f,size*2);}}foreach(var s in sigils)if(!s.taken){s.crystal.Rotate(0,45*dt,0,Space.World);s.crystal.localPosition=V(0,1.6f+Mathf.Sin(Time.time*2)*.15f,0);}}
        if(phase==Phase.Title){cam.transform.position=V(10+Mathf.Sin(Time.time*.06f),13,31);cam.transform.LookAt(V(-1,2,-6));}else{Vector3 offset=Quaternion.Euler(0,yaw,0)*V(0,2.2f+Mathf.Sin(pitch*Mathf.Deg2Rad)*10,9.5f);cam.transform.position=Vector3.Lerp(cam.transform.position,V(hero.position.x,0,hero.position.z)+offset,1-Mathf.Exp(-dt*7));cam.transform.LookAt(hero.position+Vector3.up*1.3f);}}
    void LegacyMove(Vector2 input,float dt){burstCD=Mathf.Max(0,burstCD-dt);dodgeCD=Mathf.Max(0,dodgeCD-dt);strikeCD=Mathf.Max(0,strikeCD-dt);swing=Mathf.Max(0,swing-dt);invulnerable=Mathf.Max(0,invulnerable-dt);dashTime=Mathf.Max(0,dashTime-dt);input=Vector2.ClampMagnitude(input,1);Vector3 direction=Quaternion.Euler(0,yaw,0)*V(input.x,0,input.y);if(direction.sqrMagnitude>.01f&&swing<=0)hero.rotation=Quaternion.LookRotation(direction);if(dashTime>0)direction=hero.forward;
        if(motor.isGrounded&&gravityVelocity<0)gravityVelocity=-2;gravityVelocity-=18*dt;if(jumpVelocity>0){gravityVelocity=jumpVelocity;jumpVelocity=0;}motor.Move((direction*(dashTime>0?19:5.2f)+Vector3.up*gravityVelocity)*dt);var p=hero.position;float r=new Vector2(p.x,p.z).magnitude;if(r>WorldRadius){motor.enabled=false;hero.position=V(p.x*WorldRadius/r,Mathf.Max(p.y,.05f),p.z*WorldRadius/r);motor.enabled=true;}if(hero.position.y< -5){motor.enabled=false;hero.position=V(0,.1f,19);motor.enabled=true;hp=Mathf.Max(1,hp-10);}
        walk+=dt*(input.magnitude>.1f?10:2);float step=input.magnitude>.1f?Mathf.Sin(walk)*32:0;legL.localRotation=Quaternion.Euler(step,0,0);legR.localRotation=Quaternion.Euler(-step,0,0);armL.localRotation=Quaternion.Euler(-step*.6f,0,0);armR.localRotation=swing>0?Quaternion.Euler(-90-Mathf.Sin(swing/.32f*Mathf.PI)*65,0,Mathf.Sin(swing/.32f*Mathf.PI)*80):Quaternion.Euler(step*.4f,0,0);body.localPosition=V(0,.98f+Mathf.Sin(walk*2)*.018f,0);scarf.localRotation=Quaternion.Euler(-10-Mathf.Sin(Time.time*4)*7-input.magnitude*20,0,-12);
        if(count==3&&!boss.active&&!boss.dead&&FlatDistance(hero.position,boss.spawn)<10){boss.active=true;boss.root.gameObject.SetActive(true);Notify("The Rift Warden awakens. Dodge the red circles.");PulseAt(boss.spawn,"#9ce0de",7,1);}}
    void LegacyStrike(){if(phase!=Phase.Play||strikeCD>0)return;strikeCD=.38f;swing=.32f;combo=(combo+1)%3;Foe target=null;float best=3.8f;foreach(var e in foes)if(e.active&&!e.dead){float d=FlatDistance(e.root.position,hero.position);if(d<best){best=d;target=e;}}if(target!=null){Vector3 dir=target.root.position-hero.position;dir.y=0;if(dir.sqrMagnitude>.01f)hero.rotation=Quaternion.LookRotation(dir);}foreach(var e in foes)if(e.active&&!e.dead&&FlatDistance(e.root.position,hero.position)<(e.boss?3.8f:2.8f))Hit(e,combo==2?28:20);PulseAt(hero.position+hero.forward*.8f,"#f4cb8c",2,.22f);Tone(250+combo*80,.12f);}
    void LegacyBurst(){if(phase!=Phase.Play||burstCD>0)return;burstCD=7;invulnerable=.6f;swing=.5f;PulseAt(hero.position,"#efab76",6.5f,.55f);foreach(var e in foes)if(e.active&&!e.dead&&FlatDistance(e.root.position,hero.position)<6.5f)Hit(e,65);Notify("Ember burst");Tone(140,.45f);}
    void Dodge(){if(phase!=Phase.Play||CoopWorldPaused||dodgeCD>0)return;if(CoopIsGuest)QueueCoopCommand("dodge");if(smoothMovement.sqrMagnitude>.01f)hero.rotation=Quaternion.LookRotation(MovementDirection(smoothMovement));reloadTime=swing=0;rig.Trigger("Dodge");dodgeCD=1.6f;dashTime=.2f;invulnerable=.4f;PlaySfx("dodge");}
