    void LegacyCollect(){if(phase!=Phase.Play)return;foreach(var s in sigils)if(!s.taken&&FlatDistance(hero.position,s.root.position)<2.3f){s.taken=true;s.root.gameObject.SetActive(false);count++;hp=Mathf.Min(100,hp+20);PulseAt(s.root.position,"#ffe2a1",4,.7f);Tone(880,.4f);Notify(count==3?"The rift is open. Enter the northern arena.":"Lost sigil recovered  "+count+" / 3  ·  +20 HP");SaveJourney(false);break;}}
    void LegacyHit(Foe e,float damage){if(e.dead)return;e.hp=Mathf.Max(0,e.hp-damage);PulseAt(e.root.position,e.boss?"#b9e9e3":"#e7c291",.9f,.18f);if(e.hp<=0){e.dead=true;e.root.gameObject.SetActive(false);if(e.warning)Destroy(e.warning);kills++;hp=Mathf.Min(100,hp+12);if(e.boss){phase=Phase.Win;try{if(!smoke&&File.Exists(savePath))File.Delete(savePath);}catch(IOException){}Notify("Aetherfall is safe.");}else{Notify("Riftling defeated  ·  +12 HP");SaveJourney(false);}}}
    void LegacyHurt(float damage){if(invulnerable>0||phase!=Phase.Play)return;hp=Mathf.Max(0,hp-damage);invulnerable=.7f;Tone(75,.25f);if(hp<=0)phase=Phase.Defeat;}
    void V02UpdateFoes(float dt){foreach(var e in foes){if(phase!=Phase.Play)break;if(!e.active||e.dead)continue;Vector3 dir=hero.position-e.root.position;dir.y=0;float distance=dir.magnitude;if(distance>.05f)e.root.rotation=Quaternion.LookRotation(dir);e.body.localPosition=V(0,1+Mathf.Sin(Time.time*3+e.spawn.x)*.1f,0);if(e.wind>0){e.wind-=dt;if(e.wind<=0){if(FlatDistance(hero.position,e.target)<(e.boss?3.7f:1.95f)&&hero.position.y<(e.boss?.9f:.5f))Hurt(e.boss?25:12);PulseAt(e.target,e.boss?"#eb8490":"#e5b398",e.boss?3.4f:1.7f,.3f);Destroy(e.warning);e.cooldown=e.boss?1.7f:2.2f;}}else{e.cooldown-=dt;if(distance<(e.boss?45:10)){if(distance>(e.boss?3.2f:1.45f))e.root.position+=dir.normalized*(e.boss?2.2f:1.7f)*dt;if(e.cooldown<=0&&distance<(e.boss?28:2.2f)){e.wind=e.boss?1.15f:.65f;e.target=e.boss?hero.position:e.root.position;e.target.y=.045f;float size=e.boss?6.8f:3.4f;e.warning=Cylinder("#d6747b",null,e.target,V(size,.015f,size)).gameObject;}}}}}
    void LegacyPulseAt(Vector3 at,string color,float radius,float duration){at.y=.08f;var p=Cylinder(color,null,at,V(.3f,.015f,.3f));pulses.Add(new Pulse{root=p,life=duration,max=duration,radius=radius});}
    void Tone(float frequency,float duration){PlayLegacySfx(frequency,duration);}
    void LegacyGeneratedTone(float frequency,float duration){if(!soundOn||smoke)return;int samples=(int)(22050*duration);var data=new float[samples];for(int i=0;i<samples;i++){float t=i/22050f;data[i]=Mathf.Sin(2*Mathf.PI*frequency*t)*.045f*(1-t/duration);}var clip=AudioClip.Create("Ember tone",samples,1,22050,false);clip.SetData(data,0);soundSource.PlayOneShot(clip);Destroy(clip,duration+1);}
