    void LegacySaveJourney(bool notify){if(smoke||hp<=0||boss.dead)return;int mask=0,deadMask=0;for(int i=0;i<sigils.Count;i++)if(sigils[i].taken)mask|=1<<i;for(int i=0;i<4;i++)if(foes[i].dead)deadMask|=1<<i;try{Directory.CreateDirectory(Application.persistentDataPath);string temp=savePath+".tmp";File.WriteAllText(temp,JsonUtility.ToJson(new SaveData{mask=mask,deadMask=deadMask,x=hero.position.x,z=hero.position.z,hp=hp,kills=kills,time=elapsed}));File.Copy(temp,savePath,true);File.Delete(temp);if(notify)Notify("Journey saved on this device.");}catch(Exception ex){Debug.LogWarning("Save failed: "+ex.Message);if(notify)Notify("Could not save. Check storage permissions.");}}
    void LegacyLoadJourney(){try{var d=JsonUtility.FromJson<SaveData>(File.ReadAllText(savePath));if(d==null||d.version!=1||float.IsNaN(d.x)||float.IsNaN(d.z)||Mathf.Abs(d.x)>33||Mathf.Abs(d.z)>33||d.hp<=0||float.IsNaN(d.hp))return;hp=Mathf.Clamp(d.hp,1,100);elapsed=Mathf.Max(0,d.time);kills=Mathf.Clamp(d.kills,0,4);motor.enabled=false;hero.position=V(d.x,.2f,d.z);motor.enabled=true;for(int i=0;i<3;i++){sigils[i].taken=(d.mask&(1<<i))!=0;sigils[i].root.gameObject.SetActive(!sigils[i].taken);if(sigils[i].taken)count++;}for(int i=0;i<4;i++){foes[i].dead=(d.deadMask&(1<<i))!=0;foes[i].root.gameObject.SetActive(!foes[i].dead);}}catch(Exception ex){Debug.LogWarning("Save could not be loaded: "+ex.Message);}}
