    // Executable smoke test uses the real runtime world and combat rules, without touching user saves.
    IEnumerator LegacySmokeTest(){yield return null;string result="";int code=0;try{StartGame();Require(sigils.Count==3&&foes.Count==5,"World actors");Require(motor!=null&&cam!=null,"Player and camera");Vector3 start=hero.position;Move(new Vector2(0,-1),.1f);Require(hero.position.z<start.z,"Movement: "+start+" -> "+hero.position);Burst();Require(burstCD>6,"Burst cooldown");float cd=burstCD;Burst();Require(burstCD==cd,"Cooldown gate");foreach(var s in sigils){motor.enabled=false;hero.position=s.root.position+Vector3.up*.2f;motor.enabled=true;Collect();}Require(count==3,"Three sigils");motor.enabled=false;hero.position=V(0,.2f,-17);motor.enabled=true;Move(Vector2.zero,.1f);Require(boss.active,"Boss activation");boss.hp=40;burstCD=0;Burst();Require(boss.dead&&phase==Phase.Win,"Combat victory");StartGame();Require(hp==100&&count==0&&!boss.active,"Restart reset");invulnerable=0;Hurt(100);Require(phase==Phase.Defeat,"Defeat");result="PASS: real Unity scene, movement, ability cooldown, all sigils, boss gating, combat victory, restart, defeat.";}catch(Exception ex){result="FAIL: "+ex;code=1;}Debug.Log("TEJA_SMOKE "+result);var args=TejaPlatformV7.LaunchArguments;int ix=Array.IndexOf(args,"-tejaTestResult");if(ix>=0&&ix+1<args.Length)File.WriteAllText(args[ix+1],result);Application.Quit(code);}
    IEnumerator LegacyCapturePreview(){
        var args=TejaPlatformV7.LaunchArguments;int ix=Array.IndexOf(args,"-tejaPreviewDir");
        if(ix<0||ix+1>=args.Length){Application.Quit(1);yield break;}
        string dir=args[ix+1];Directory.CreateDirectory(dir);
        yield return new WaitForSecondsRealtime(2);yield return new WaitForEndOfFrame();
        RenderPreview(Path.Combine(dir,"unity-title.png"));
        yield return new WaitForSecondsRealtime(1);StartGame();
        yield return new WaitForSecondsRealtime(2);yield return new WaitForEndOfFrame();
        RenderPreview(Path.Combine(dir,"unity-gameplay.png"));
        yield return new WaitForSecondsRealtime(1);Debug.Log("TEJA_PREVIEW_OK");Application.Quit(0);
    }
    void RenderPreview(string path){
        var visibility=new bool[v6DetailRenderers.Count];for(int i=0;i<v6DetailRenderers.Count;i++)if(v6DetailRenderers[i]){visibility[i]=v6DetailRenderers[i].enabled;v6DetailRenderers[i].enabled=true;}
        var rt=new RenderTexture(1280,720,24,RenderTextureFormat.ARGB32);rt.antiAliasing=2;
        var previous=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;
        var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();
        File.WriteAllBytes(path,tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=previous;rt.Release();Destroy(rt);Destroy(tex);
        for(int i=0;i<v6DetailRenderers.Count;i++)if(v6DetailRenderers[i])v6DetailRenderers[i].enabled=visibility[i];
    }
    static void Require(bool ok,string label){if(!ok)throw new Exception(label);}
